urlset:
{%- set posts = get_section(path="posts/_index.md") -%}
{%- set latest_post_date = config.extra.site_launch -%}
{%- if posts.pages | length > 0 -%}
  {%- set newest = posts.pages | first -%}
  {%- set newest_date = newest.date -%}
  {%- if newest.updated -%}{%- set newest_date = newest.updated -%}{%- endif -%}
  {%- set latest_post_date = newest_date | date(format="%Y-%m-%d", timezone="UTC") -%}
{%- endif %}

        {{ config.base_url | escape_xml | safe }}/
        {{ latest_post_date }}

{%- for entry in entries %}
  {%- if entry.permalink != config.base_url ~ "/" %}

        {{ entry.permalink | escape_xml | safe }}
        {%- if entry.updated %}
        {{ entry.updated | date(format="%Y-%m-%d", timezone="UTC") }}
        {%- endif %}

  {%- endif %}
{%- endfor %}
